# Sum of profiles shifted by multiples of pitch
import numpy as np

# Let's interpolate profile
ys = sorted(profile.keys())
vals = [profile[y] for y in ys]

def p(y):
    return np.interp(y, ys, vals, left=0, right=0)

for pitch in [30, 40, 45, 50, 60]:
    # Suppose passes at k * pitch for k in range(-10, 11)
    y_test = np.linspace(-pitch/2, pitch/2, 101)
    dft = np.zeros_like(y_test)
    for k in range(-10, 11):
        dft += p(y_test - k * pitch)
    print(f'pitch={pitch}: min={dft.min():.1f}, max={dft.max():.1f}, mean={dft.mean():.1f}, ripple={dft.max()-dft.min():.1f}')
