profile = {-100: 6, -80: 4, -60: 14, -40: 21, -20: 31, 0: 35, 20: 27, 40: 21, 60: 11, 80: 6, 100: 1}
ys = sorted(profile.keys())
vals = [profile[y] for y in ys]

def p(y):
    if y <= ys[0] or y >= ys[-1]: return 0.0
    for i in range(len(ys)-1):
        if ys[i] <= y <= ys[i+1]:
            t = (y - ys[i]) / (ys[i+1] - ys[i])
            return vals[i] + t * (vals[i+1] - vals[i])
    return 0.0

for pitch in [25, 30, 35, 40, 45, 50, 60]:
    tests = [p(y) for y in [0]]
    # test across one period
    period = [(-pitch/2.0 + pitch * i / 100.0) for i in range(101)]
    dfts = []
    for y in period:
        val = sum(p(y - k * pitch) for k in range(-15, 16))
        dfts.append(val)
    print(f'pitch={pitch:2d}: min={min(dfts):.1f}, max={max(dfts):.1f}, mean={sum(dfts)/len(dfts):.1f}, ripple={max(dfts)-min(dfts):.1f}')
"

