python3 -c "
import math
R = 100.0
def circ_int(a, b):
    def F(u):
        return 0.5 * (u * math.sqrt(R*R - u*u) + R*R * math.asin(u/R))
    return F(b) - F(a)

total = circ_int(-100, 100)
for M in [0, 30, 50, 60, 70, 80]:
    # x_start = -M, so at x=30, u_start = -M - 30 = -(M+30)
    u_start = max(-100.0, -(M + 30))
    frac = circ_int(u_start, 100) / total
    print(f'margin={M}: fraction at x=30 is {frac*100:.1f}%')
"

